/**
 * Transport specifies how a harness subprocess is reached on its host.
 */
export type Transport = string;
export const TransportLocal: Transport = "local"; // local subprocess on the same host as llm-bridge-server
export const TransportSSH: Transport = "ssh"; // SSH from server to remote machine, server forks subprocess via sshd
export const TransportRunner: Transport = "runner"; // remote llm-bridge-runner daemon dialed in over WebSocket
/**
 * Machine represents a host where harness subprocesses can run. One row per
 * physical/virtual host. Multiple instances may share a machine (e.g.
 * claude_code and codex on the same laptop). Created either explicitly
 * (local/ssh) or auto-created when an llm-bridge-runner enrolls.
 */
export interface Machine {
  id: string; // m_<id>
  name: string; // unique, human label: "linode", "wsl-claude"
  emoji?: string; // optional UI accent: 🏠 🖥 ☁ etc.
  hostname?: string; // network address (Tailscale name, IP, …); empty for runner
  os?: string; // GOOS reported by runner, or set on create
  arch?: string; // GOARCH
  transport: Transport;
  ssh_user?: string;
  ssh_key_path?: string;
  ssh_port?: number /* int */; // default 22
  default_working_dir?: string;
  user?: string; // runner-side OS user (display only)
  notes?: string;
  last_seen_at?: string;
  created_at: string;
  updated_at: string;
}
/**
 * Instance represents a configured harness deployment on a machine. The
 * Machine pointer is populated by API responses for client convenience;
 * internal storage code reads from the machines table directly.
 */
export interface Instance {
  id: string;
  harness_type: Harness;
  name: string;
  machine_id: string;
  working_dir?: string; // overrides Machine.DefaultWorkingDir for this instance
  max_concurrent_sessions: number /* int */;
  enabled: boolean;
  created_at: string;
  updated_at: string;
  /**
   * Machine is populated by API responses (denormalized for the client).
   * Storage and routing code looks up the machine by ID directly.
   */
  machine?: Machine;
}
/**
 * InstanceCredential binds a credential to a harness instance with priority.
 */
export interface InstanceCredential {
  instance_id: string;
  credential_id: string;
  priority: number /* int */; // 0 = primary, 1+ = fallbacks
  enabled: boolean;
}
/**
 * InstanceStatus aggregates runtime status for an instance.
 */
export interface InstanceStatus {
  instance: Instance;
  active_sessions: number /* int */;
  credentials: InstanceCredential[];
  reachable: boolean; // SSH/runner connectivity check
  last_checked: string;
}
/**
 * RunnerEnrollment is a one-time-use token that lets a runner self-register
 * a Machine without prior server-side configuration. Minted by an admin
 * (CLI or API), redeemed by the runner via POST /api/runner/enroll.
 */
export interface RunnerEnrollment {
  id: string; // enr_<id>
  expires_at: string;
  used_at?: string; // zero if unused
  consumed_machine_id?: string; // set when redeemed
  created_at: string;
}

