export const ProviderAnthropic: Provider = "anthropic";
export const ProviderOpenAI: Provider = "openai";
export const ProviderGemini: Provider = "gemini";
export const ProviderOpenRouter: Provider = "openrouter";
/**
 * Role is the normalized message role across all providers.
 */
export type Role = string;
export const RoleSystem: Role = "system";
export const RoleUser: Role = "user";
export const RoleAssistant: Role = "assistant";
export const RoleTool: Role = "tool";
/**
 * NativeRole maps to provider-specific role strings.
 */
