export const SessionAwaitingPermission: SessionState = "awaiting_permission"; // hook prompt open, blocking on approve/deny
export const SessionAwaitingUser: SessionState = "awaiting_user"; // turn ended, expects user reply (best-effort heuristic)
/**
 * Self-healing wait (no action; will resume).
 */
export const SessionRateLimited: SessionState = "rate_limited"; // provider backoff
export const SessionPaused: SessionState = "paused"; // user-interrupted, can be resumed
/**
 * Quiet but alive.
 */
export const SessionIdle: SessionState = "idle"; // between turns, no terminal signal
/**
 * Terminal.
 */
export const SessionCompleted: SessionState = "completed"; // agent signaled work done
export const SessionError: SessionState = "error"; // last activity ended in error
export const SessionAborted: SessionState = "aborted"; // killed by user/system (intentional)
export const SessionDisconnected: SessionState = "disconnected"; // process gone unexpectedly (no clean exit)
/**
 * Deprecated: replaced by SessionModelGenerating / SessionToolRunning.
 * Kept valid during the migration window so harness packages that still
 * emit EventSessionState continue to compile. Will be removed once all
 * llm-bridge-* harnesses stop emitting SessionState.
 */
export const SessionRunning: SessionState = "running";
/**
 * Deprecated: renamed to SessionAwaitingPermission. Kept valid during
 * the migration window for the same reason as SessionRunning above.
 */
export const SessionWaitingApproval: SessionState = "waiting_on_approval";

